INSERT INTO article(type,uploadTime,title,editor,editor_id,reviewer,reviewer_id,content,review_state,likes,image_path,video_path) SELECT '支部动态',NOW(),'【示例专题】以学铸魂：让理论学习融入日常','电光党建示例编辑','admin','本地示例审核','admin','<p><strong>示例内容说明：</strong>本文为本地演示专题，不代表已开展的真实活动。</p><p><img src="http://127.0.0.1:8080/uploads/banner-1.png" style="width:100%;height:auto" /></p><p>理论学习不止于阅读，更在于联系实际、学思结合。建议从原文阅读、问题研讨、行动复盘三个环节入手，让每一次学习都有记录、有思考、有收获。</p><h2>制定一周学习计划</h2><p>每周选定一个主题，安排一次集中阅读与一次交流讨论。学习笔记可以围绕“我理解了什么、与我的学习科研有什么联系、下一步准备怎么做”展开。</p><h2>把学习成果转化为行动</h2><p>从身边的小问题入手，在服务同学、规范实验记录和提升协作效率中检验学习成效。</p><p><strong>交流思考：</strong>结合自己的学习和工作，你准备从哪一件小事开始行动？</p>',1,0,'http://127.0.0.1:8080/uploads/banner-1.png','' WHERE NOT EXISTS(SELECT 1 FROM article WHERE title='【示例专题】以学铸魂：让理论学习融入日常');
