INSERT INTO article(type,uploadTime,title,editor,editor_id,reviewer,reviewer_id,content,review_state,likes,image_path,video_path) SELECT '支部动态',NOW(),'【示例专题】支部共建：把组织活力转化为协作动力','电光党建示例编辑','admin','本地示例审核','admin','<p><strong>示例内容说明：</strong>本文为本地演示专题，不代表已开展的真实活动。</p><p><img src="http://127.0.0.1:8080/uploads/banner-2.png" style="width:100%;height:auto" /></p><p>支部共建可以从共同需求出发，让组织优势与学科资源互相连接。本文提供一份可复用的共建活动策划思路，供支部工作参考。</p><h2>从需求清单开始</h2><p>围绕科研互助、学业支持、实验室安全和志愿服务，分别梳理资源清单与需求清单，选择一个小切口确定活动主题。</p><h2>让协作形成闭环</h2><p>活动前明确分工与时间节点，活动中记录过程，活动后收集反馈。用可落实的任务清单延续交流成果。</p><p><strong>交流思考：</strong>结合自己的学习和工作，你准备从哪一件小事开始行动？</p>',1,0,'http://127.0.0.1:8080/uploads/banner-2.png','' WHERE NOT EXISTS(SELECT 1 FROM article WHERE title='【示例专题】支部共建：把组织活力转化为协作动力');
