INSERT INTO article(type,uploadTime,title,editor,editor_id,reviewer,reviewer_id,content,review_state,likes,image_path,video_path) SELECT '支部动态',NOW(),'【示例专题】志愿服务：让一份微光温暖身边的人','电光党建示例编辑','admin','本地示例审核','admin','<p><strong>示例内容说明：</strong>本文为本地演示专题，不代表已开展的真实活动。</p><p><img src="http://127.0.0.1:8080/uploads/banner-3.png" style="width:100%;height:auto" /></p><p>志愿服务既是力所能及的付出，也是理解社会、增进协作的过程。参与服务时，应尊重服务对象，注重实际需求，避免形式化。</p><h2>选择适合自己的服务</h2><p>可以从校园引导、科普讲解、学习帮扶和社区便民服务等方向开始，根据时间与能力合理安排参与频次。</p><h2>做好准备与复盘</h2><p>服务前了解岗位要求，保护服务对象隐私；服务后记录遇到的问题和改进建议，让下一次服务更周到。</p><p><strong>交流思考：</strong>结合自己的学习和工作，你准备从哪一件小事开始行动？</p>',1,0,'http://127.0.0.1:8080/uploads/banner-3.png','' WHERE NOT EXISTS(SELECT 1 FROM article WHERE title='【示例专题】志愿服务：让一份微光温暖身边的人');
