INSERT INTO article(type,uploadTime,title,editor,editor_id,reviewer,reviewer_id,content,review_state,likes,image_path,video_path) SELECT '支部动态',NOW(),'【示例专题】科创报国：在严谨求实中追寻光的答案','电光党建示例编辑','admin','本地示例审核','admin','<p><strong>示例内容说明：</strong>本文为本地演示专题，不代表已开展的真实活动。</p><p><img src="http://127.0.0.1:8080/uploads/banner-4.png" style="width:100%;height:auto" /></p><p>光电学科的探索离不开扎实的基础和长期的积累。把个人成长与团队需要相连接，可以从每一份真实、完整、可复现的实验记录做起。</p><h2>把求实写进实验过程</h2><p>如实记录实验条件、参数与异常情况，主动复核数据来源，规范引用资料。面对不符合预期的结果，也应保留完整记录。</p><h2>在协作中提升能力</h2><p>开展跨年级经验交流，分享仪器使用规范和问题排查方法。让知识在团队中传递，让创新建立在可靠的基础之上。</p><p><strong>交流思考：</strong>结合自己的学习和工作，你准备从哪一件小事开始行动？</p>',1,0,'http://127.0.0.1:8080/uploads/banner-4.png','' WHERE NOT EXISTS(SELECT 1 FROM article WHERE title='【示例专题】科创报国：在严谨求实中追寻光的答案');
