INSERT INTO article(type,uploadTime,title,editor,editor_id,reviewer,reviewer_id,content,review_state,likes,image_path,video_path) SELECT '支部动态',NOW(),'【示例专题】青年成长：在知行合一中找到奋进坐标','电光党建示例编辑','admin','本地示例审核','admin','<p><strong>示例内容说明：</strong>本文为本地演示专题，不代表已开展的真实活动。</p><p><img src="http://127.0.0.1:8080/uploads/banner-5.png" style="width:100%;height:auto" /></p><p>成长既需要远大的目标，也需要具体而持续的行动。可以从学习、实践与服务三个维度，为自己制定一份可执行的成长计划。</p><h2>将目标拆解为小任务</h2><p>把阶段目标拆成每周可以完成的事项，例如阅读一篇文献、参与一次交流、完成一项服务。根据实际进展及时调整。</p><h2>用复盘积累成长经验</h2><p>每月回顾一次自己的计划：哪些行动有效，哪些方法需要改变，哪些协作值得延续。把收获与同伴分享，在互助中共同进步。</p><p><strong>交流思考：</strong>结合自己的学习和工作，你准备从哪一件小事开始行动？</p>',1,0,'http://127.0.0.1:8080/uploads/banner-5.png','' WHERE NOT EXISTS(SELECT 1 FROM article WHERE title='【示例专题】青年成长：在知行合一中找到奋进坐标');
